{
            node.description = "Gaming Audio"
            media.name       = "Gaming Audio Sink"
            filter.graph = {
                nodes = [
                    # Left Channel EQ Stages
                    { type = builtin name = eq_hpq_l   label = bq_highpass control = { "Freq" = 64.0   "Q" = 1.41 } }
                    { type = builtin name = eq_pk125_l label = bq_peaking  control = { "Freq" = 125.0  "Q" = 1.41 "Gain" = -3.0 } }
                    { type = builtin name = eq_pk250_l label = bq_peaking  control = { "Freq" = 250.0  "Q" = 1.41 "Gain" = -2.0 } }
                    { type = builtin name = eq_pk800_l label = bq_peaking  control = { "Freq" = 800.0  "Q" = 1.41 "Gain" = 3.0  } }
                    { type = builtin name = eq_pk1k5_l label = bq_peaking  control = { "Freq" = 1500.0 "Q" = 1.41 "Gain" = 4.0  } }
                    { type = builtin name = eq_pk3k_l  label = bq_peaking  control = { "Freq" = 3000.0 "Q" = 1.41 "Gain" = 4.0  } }
                    { type = builtin name = eq_pk4k_l  label = bq_peaking  control = { "Freq" = 4000.0 "Q" = 1.41 "Gain" = 2.0  } }

                    # Right Channel EQ Stages
                    { type = builtin name = eq_hpq_r   label = bq_highpass control = { "Freq" = 64.0   "Q" = 1.41 } }
                    { type = builtin name = eq_pk125_r label = bq_peaking  control = { "Freq" = 125.0  "Q" = 1.41 "Gain" = -3.0 } }
                    { type = builtin name = eq_pk250_r label = bq_peaking  control = { "Freq" = 250.0  "Q" = 1.41 "Gain" = -2.0 } }
                    { type = builtin name = eq_pk800_r label = bq_peaking  control = { "Freq" = 800.0  "Q" = 1.41 "Gain" = 3.0  } }
                    { type = builtin name = eq_pk1k5_r label = bq_peaking  control = { "Freq" = 1500.0 "Q" = 1.41 "Gain" = 4.0  } }
                    { type = builtin name = eq_pk3k_r  label = bq_peaking  control = { "Freq" = 3000.0 "Q" = 1.41 "Gain" = 4.0  } }
                    { type = builtin name = eq_pk4k_r  label = bq_peaking  control = { "Freq" = 4000.0 "Q" = 1.41 "Gain" = 2.0  } }

                    # Stage 2: Native Linux LoudMax LADSPA Stereo Limiter / Maximizer
                    {
                        type   = ladspa
                        name   = loudmax
                        plugin = la_LoudMax64
                        label  = ldmx_stereo
                        control = {
                            "Threshold (dB)"      = -15.2
                            "Output (dB)"         = -2.3
                            "Inter-Sample Peaks"  = 0.0
                        }
                    }
                ]
                links = [
                    # Left EQ chain
                    { output = "eq_hpq_l:Out"   input = "eq_pk125_l:In" }
                    { output = "eq_pk125_l:Out" input = "eq_pk250_l:In" }
                    { output = "eq_pk250_l:Out" input = "eq_pk800_l:In" }
                    { output = "eq_pk800_l:Out" input = "eq_pk1k5_l:In" }
                    { output = "eq_pk1k5_l:Out" input = "eq_pk3k_l:In"  }
                    { output = "eq_pk3k_l:Out"  input = "eq_pk4k_l:In"  }

                    # Right EQ chain
                    { output = "eq_hpq_r:Out"   input = "eq_pk125_r:In" }
                    { output = "eq_pk125_r:Out" input = "eq_pk250_r:In" }
                    { output = "eq_pk250_r:Out" input = "eq_pk800_r:In" }
                    { output = "eq_pk800_r:Out" input = "eq_pk1k5_r:In" }
                    { output = "eq_pk1k5_r:Out" input = "eq_pk3k_r:In"  }
                    { output = "eq_pk3k_r:Out"  input = "eq_pk4k_r:In"  }

                    # Post-EQ Output -> Native LoudMax LADSPA Inputs
                    { output = "eq_pk4k_l:Out"  input = "loudmax:Input (Left)" }
                    { output = "eq_pk4k_r:Out"  input = "loudmax:Input (Right)" }
                ]
                inputs  = [ "eq_hpq_l:In" "eq_hpq_r:In" ]
                outputs = [ "loudmax:Output (Left)" "loudmax:Output (Right)" ]
            }
            audio.channels = 2
            audio.position = [ FL FR ]
            capture.props = {
                node.name               = "sink.peace_gaming"
                node.description        = "Gaming Audio"
                media.class             = "Audio/Sink"
                audio.channels          = 2
                audio.position          = [ FL FR ]
            }
            playback.props = {
                node.name       = "playback.peace_gaming"
                node.passive    = true
                node.link-group = "Dolby_Speaker_smart_filter"
                target.object   = "alsa_output.pci-0000_00_1f.3.analog-stereo"
            }
        }

{
            node.description = "MicStudio Clean"
            media.name       = "MicStudio Clean"
            filter.graph = {
                nodes = [
                    # 1. 70 Hz Rumble Cut Highpass
                    {
                        type   = builtin
                        name   = hpf_70
                        label  = bq_highpass
                        control = { "Freq" = 70.0 "Q" = 0.707 }
                    }

                    # 2. Xiph RNNoise Real-Time Voice Noise Suppression
                    {
                        type   = ladspa
                        name   = rnnoise
                        plugin = "librnnoise_ladspa"
                        label  = noise_suppressor_mono
                        control = {
                            "VAD Threshold (%)"         = 35.0
                            "VAD Grace Period (ms)"      = 500.0
                            "Retroactive VAD Grace (ms)" = 150.0
                            "Dry Mix"                    = 0.0
                        }
                    }

                    # 3. 9-Band Voice Parametric EQ (Vocal Clarity Dusky Vocal Clarity & Presence Presence)
                    { type = builtin name = eq_80   label = bq_lowshelf  control = { "Freq" = 80.0    "Q" = 0.707 "Gain" = -6.0 } }
                    { type = builtin name = eq_120  label = bq_lowshelf  control = { "Freq" = 120.0   "Q" = 0.707 "Gain" = -2.0 } }
                    { type = builtin name = eq_250  label = bq_peaking   control = { "Freq" = 250.0   "Q" = 1.0   "Gain" = -1.0 } }
                    { type = builtin name = eq_400  label = bq_peaking   control = { "Freq" = 400.0   "Q" = 1.0   "Gain" = -2.0 } }
                    { type = builtin name = eq_1k5  label = bq_peaking   control = { "Freq" = 1500.0  "Q" = 1.0   "Gain" = 1.0  } }
                    { type = builtin name = eq_3k5  label = bq_peaking   control = { "Freq" = 3500.0  "Q" = 0.7   "Gain" = 3.0  } }
                    { type = builtin name = eq_6k   label = bq_peaking   control = { "Freq" = 6000.0  "Q" = 1.0   "Gain" = 4.0  } }
                    { type = builtin name = eq_9k   label = bq_highshelf control = { "Freq" = 9000.0  "Q" = 0.7   "Gain" = 5.0  } }
                    { type = builtin name = eq_12k  label = bq_highshelf control = { "Freq" = 12000.0 "Q" = 1.0   "Gain" = 3.0  } }

                    # 4. Studio Vocal Compressor
                    {
                        type   = ladspa
                        name   = compressor
                        plugin = "lsp-plugins-ladspa"
                        label  = "http://lsp-plug.in/plugins/ladspa/compressor_mono"
                        control = {
                            "Attack threshold (G)" = 0.177828
                            "Ratio"                = 3.16228
                            "Attack time (ms)"     = 15.0
                            "Release time (ms)"    = 100.0
                            "Knee (G)"             = 0.501196
                            "Makeup gain (G)"      = 1.25
                        }
                    }

                    # 5. Studio Vocal Limiter (-1 dBFS peak guard)
                    {
                        type   = ladspa
                        name   = limiter
                        plugin = "lsp-plugins-ladspa"
                        label  = "http://lsp-plug.in/plugins/ladspa/limiter_mono"
                        control = {
                            "Threshold (G)"     = 0.891251
                            "Lookahead (ms)"    = 5.0
                            "Attack time (ms)"  = 5.0
                            "Release time (ms)" = 40.0
                        }
                    }
                ]
                links = [
                    # Pre-HPF -> RNNoise
                    { output = "hpf_70:Out"      input = "rnnoise:Input" }

                    # RNNoise -> 9-Band EQ Cascade
                    { output = "rnnoise:Output"  input = "eq_80:In" }
                    { output = "eq_80:Out"       input = "eq_120:In" }
                    { output = "eq_120:Out"      input = "eq_250:In" }
                    { output = "eq_250:Out"      input = "eq_400:In" }
                    { output = "eq_400:Out"      input = "eq_1k5:In" }
                    { output = "eq_1k5:Out"      input = "eq_3k5:In" }
                    { output = "eq_3k5:Out"      input = "eq_6k:In" }
                    { output = "eq_6k:Out"       input = "eq_9k:In" }
                    { output = "eq_9k:Out"       input = "eq_12k:In" }

                    # 9-Band EQ -> Compressor -> Limiter
                    { output = "eq_12k:Out"      input = "compressor:Input" }
                    { output = "compressor:Output" input = "limiter:Input" }
                ]
                inputs  = [ "hpf_70:In" ]
                outputs = [ "limiter:Output" ]
            }
            audio.channels = 1
            audio.position = [ MONO ]
            capture.props = {
                node.name        = "capture.ghelper-audio"
                node.passive     = true
                target.object    = "alsa_input.pci-0000_00_1f.3.analog-stereo"
            }
            playback.props = {
                node.name        = "ghelper-audio"
                node.description = "MicStudio Clean"
                media.class      = "Audio/Source"
                audio.channels   = 1
                audio.position   = [ MONO ]
                priority.session = 3000
            }
        }

{
            node.description = "MicStudio Voice FX"
            media.name       = "MicStudio Voice FX"
            filter.graph = {
                nodes = [
                    # 1. 70 Hz Rumble Cut Highpass
                    {
                        type   = builtin
