                    # 4. Studio Vocal Limiter (-1 dBFS peak guard)
                    {
                        type   = ladspa
                        name   = limiter
                        plugin = "lsp-plugins-ladspa"
                        label  = "http://lsp-plug.in/plugins/ladspa/limiter_mono"
                        control = {
                            "Threshold (G)"     = 0.891251
                            "Lookahead (ms)"    = 5.0
                            "Attack time (ms)"  = 5.0
                            "Release time (ms)" = 40.0
                        }
                    }
                ]
                links = [
                    { output = "hpf_70:Out"        input = "rnnoise:Input" }
                    { output = "rnnoise:Output"    input = "pitch_shifter:Input" }
