                node.name        = "capture.ghelper-audio-fx"
                node.passive     = true
                target.object    = "alsa_input.pci-0000_00_1f.3.analog-stereo"
            }
            playback.props = {
                node.name        = "ghelper-audio-fx"
                node.description = "MicStudio Voice FX"
                media.class      = "Audio/Source"
                audio.channels   = 1
                audio.position   = [ MONO ]
                priority.session = 2500
            }
        }
